let saved={unlocked:1,best:levels.map(()=>0),completed:levels.map(()=>false)};try{const d=JSON.parse(localStorage.getItem('star-hop-v1'));if(d&&Array.isArray(d.best)&&Array.isArray(d.completed)){saved.unlocked=Math.max(1,Math.min(levels.length,Number(d.unlocked)||1));saved.best=levels.map((_,i)=>Math.max(0,Math.min(3,Number(d.best[i])||0)));saved.completed=levels.map((_,i)=>!!d.completed[i]);for(let i=0;i<levels.length-1;i++)if(saved.completed[i])saved.unlocked=Math.max(saved.unlocked,i+2);}}catch{}
let index=0,state='ready',p,stars,t=0,deaths=0,particles=[],last=0,acc=0,keys={left:false,right:false,crouch:false},muted=true,audioCtx;
let tiles=[],checkpoint=false,portalCooldown=0,notice='',noticeUntil=0,boss=null,collectedKey=false;
const crouchInputs=new Set();
function setCrouchInput(source,pressed){if(pressed)crouchInputs.add(source);else crouchInputs.delete(source);keys.crouch=crouchInputs.size>0;$('crouch').setAttribute('aria-pressed',String(keys.crouch));}
function resetControls(){keys.left=keys.right=keys.crouch=false;crouchInputs.clear();$('crouch').setAttribute('aria-pressed','false');}
function updatePosture(){let height=keys.crouch?18:35;const feet=p.y+p.h;if(height>p.h){for(const [x,y,w,h] of levels[index].beams||[]){if(p.x+p.w>x&&p.x<x+w&&feet-height<y+h&&feet>y){height=p.h;break;}}for(const [x,y] of levels[index].spikes){const bounds=spikeBounds(x,y,feet-height,p.y);if(bounds&&p.x+p.w>bounds[0]&&p.x<bounds[1]){height=p.h;break;}}}p.y=feet-height;p.h=height;p.crouched=height<35;}
function circleHitsPlayer(x,y,radius){if(!p.crouched)return Math.hypot(p.x+p.w/2-x,p.y+18-y)<radius+13;const nx=Math.max(p.x,Math.min(x,p.x+p.w)),ny=Math.max(p.y,Math.min(y,p.y+p.h));return (x-nx)**2+(y-ny)**2<radius**2;}
function tone(freq,duration=.1){if(muted)return;try{audioCtx??=new(window.AudioContext||window.webkitAudioContext)();audioCtx.resume();let o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type='sine';o.frequency.setValueAtTime(freq,audioCtx.currentTime);g.gain.setValueAtTime(.07,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+duration);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+duration);}catch{}}
function map(){ $('levels').innerHTML='';levels.forEach((l,i)=>{if([0,8,15,22,29].includes(i)){let h=document.createElement('div');h.className='chapter';h.textContent={0:'01 · 机关训练营',8:'02 · 星光进阶赛',15:'03 · 云海挑战赛',22:'04 · 星河大师赛',29:'05 · 最终 Boss 战'}[i];$('levels').appendChild(h);}let b=document.createElement('button');b.className='level'+(i===index?' active':'');b.disabled=i>=saved.unlocked;b.innerHTML=`<span class="num">${String(i+1).padStart(2,'0')}</span><span><span class="level-name">${l.name}</span><span class="level-sub">${l.sub}</span></span><span class="level-end">${saved.completed[i]?'★'.repeat(saved.best[i])||'✓':'→'}</span>`;b.onclick=()=>load(i,true);$('levels').appendChild(b)});$('progress').textContent=saved.completed.filter(Boolean).length+' / '+levels.length+' 完成';}
function makeTiles(){tiles=levels[index].platforms.map(([x,y,w,kind='normal',amount=0,speed=1])=>({x,y,w,kind,amount,speed,baseX:x,baseY:y,active:true,trigger:-1,dx:0,dy:0}));advanceTiles(0);}
function advanceTiles(dt){for(const tile of tiles){const ox=tile.x,oy=tile.y;if(tile.kind==='move')tile.x=tile.baseX+Math.sin(t*tile.speed)*tile.amount;if(tile.kind==='lift')tile.y=tile.baseY-Math.sin(t*tile.speed)*tile.amount;tile.dx=tile.x-ox;tile.dy=tile.y-oy;if(tile.kind==='phase')tile.active=((t+tile.amount)%tile.speed)<tile.speed*.7;if(tile.kind==='crumble'&&tile.trigger>=0){tile.trigger+=dt;tile.active=tile.trigger<(levels[index].crumbleDelay||.9);if(tile.trigger>=(levels[index].crumbleDelay||.9)+3){tile.trigger=-1;tile.active=true;}}}}
function newPlayer(x=45,y=380){return {x,y,w:28,h:35,crouched:false,vx:0,vy:0,jumps:0,ground:false,coyote:0,riding:null};}
function load(i,play=false){index=i;p=newPlayer(45,levels[i].platforms[0][1]-50);boss=levels[i].boss?{hp:5,max:5,cooldown:0,clock:0,shots:[],x:680,y:370}:null;collectedKey=false;stars=levels[i].stars.map(([x,y])=>({x,y,got:false}));t=0;particles=[];checkpoint=false;portalCooldown=0;notice='';noticeUntil=0;makeTiles();resetControls();state=play?'playing':'ready';if(play)c.focus({preventScroll:true});$('overlay').hidden=play;$('levelNo').textContent=String(i+1).padStart(2,'0')+' / '+String(levels.length).padStart(2,'0');$('levelName').textContent=levels[i].name;$('route').textContent=levels[i].route;$('bossbar').hidden=!boss;$('checkpoint').textContent='⚑ 检查点未激活';$('pause').textContent='Ⅱ';hud();map();}
function respawn(){if(!checkpoint){load(index,true);return;}const [x,y]=levels[index].checkpoint;p=newPlayer(x,y-35);makeTiles();portalCooldown=1;particles=[];if(boss){boss.shots=[];boss.clock=0;boss.cooldown=1;}state='playing';resetControls();$('overlay').hidden=true;c.focus({preventScroll:true});say('从绿旗继续！已收集的星星保留。');}
function say(message){notice=message;noticeUntil=t+3;}
function hud(){if(levels[index].requiredStars)$('route').textContent='收星开门：'+stars.filter(s=>s.got).length+' / '+levels[index].requiredStars;if(boss){$('bosshealth').textContent=boss.hp>0?'♥'.repeat(boss.hp)+'♡'.repeat(boss.max-boss.hp):'已击败！终点已开启';$('bossphase').textContent=boss.hp<=0?'胜利':boss.hp<=2?'第二阶段 · 双弹连发':'第一阶段 · 躲避反击';}$('hint').textContent=t<noticeUntil?notice:levels[index].hint;$('stars').textContent=stars.filter(s=>s.got).length+' / 3';let sec=Math.floor(t);$('timer').textContent=String(Math.floor(sec/60)).padStart(2,'0')+':'+String(sec%60).padStart(2,'0');}
function modal(title,text,action,label){$('modalTitle').textContent=title;$('modalText').textContent=text;$('action').textContent=label;$('action').onclick=action;$('extra').hidden=true;$('overlay').hidden=false;resetControls();}
function jump(){if(state!=='playing')return;if(p.jumps<2){p.vy=-470;p.jumps++;p.ground=false;p.riding=null;p.coyote=0;tone(p.jumps===1?440:590,.09);burst(p.x+14,p.y+p.h,'#ffffff',6);}}
function burst(x,y,color,n=12){for(let i=0;i<n;i++)particles.push({x,y,vx:(Math.random()-.5)*180,vy:(Math.random()-.7)*180,life:.6,color});}
function fail(){if(state!=='playing')return;state='dead';deaths++;tone(160,.2);modal('再来一次，这次一定行',checkpoint?'绿旗已激活，收集的星星会保留。\n从检查点继续挑战吧！':'换个时机，或者试试另一条路线。\n这一关可以无限次挑战。',respawn,checkpoint?'从检查点继续 →':'重新挑战 ↻');}
function win(){state='won';let count=stars.filter(s=>s.got).length;saved.best[index]=Math.max(saved.best[index],count);saved.completed[index]=true;saved.unlocked=Math.max(saved.unlocked,Math.min(levels.length,index+2));try{localStorage.setItem('star-hop-v1',JSON.stringify(saved))}catch{}tone(880,.3);map();modal(index===levels.length-1?'你点亮了整片星空！':'漂亮！又向星空近了一步',index===levels.length-1?`${levels.length} 关全部通关 · 最佳收集 ${saved.best.reduce((a,b)=>a+b,0)} / ${levels.length*3} 颗星\n回到任意关卡，继续挑战满星吧。`:`${levels[index].name} 已完成 · 收集 ${count} / 3 颗星\n用时 ${$('timer').textContent}，下一段冒险正在等你。`,()=>load(index===levels.length-1?0:index+1,true),index===levels.length-1?'重新出发 →':'下一关 →');$('extra').hidden=false;$('extra').onclick=()=>load(index,true);}
function pause(){if(state==='playing'){state='paused';modal('让冒险歇一会儿','准备好后，继续向星星出发。',()=>{state='playing';$('overlay').hidden=true;$('pause').textContent='Ⅱ';c.focus({preventScroll:true})},'继续冒险 →');$('pause').textContent='▶'}else if(state==='paused'){$('action').click()}}
function enemy(){const e=levels[index].enemy;return e?{x:e.x+Math.sin(t*e.speed)*e.range,y:e.y+Math.sin(t*3)*12}:null;}
function spikeBounds(x,y,top,bottom){if(bottom<=y-25||top>=y)return null;const half=14*Math.min(1,(bottom-(y-25))/25);return [x+14-half,x+14+half];}
function hammerPositions(){return (levels[index].hammers||[]).map(([x,y,length,speed])=>{const angle=Math.sin(t*speed)*1.05;return {anchorX:x,anchorY:y,x:x+Math.sin(angle)*length,y:y+Math.cos(angle)*length};});}
function updateBoss(dt,previousBottom){if(!boss||boss.hp<=0)return;boss.cooldown=Math.max(0,boss.cooldown-dt);boss.x=680+Math.sin(t*.8)*70;boss.clock+=dt;const interval=boss.hp<=2?1.9:2.8;
if(boss.clock>=interval){boss.clock=0;const direction=p.x+14<boss.x?-1:1;boss.shots.push({x:boss.x,y:410,vx:direction*(boss.hp<=2?210:175),vy:0});if(boss.hp<=2)boss.shots.push({x:boss.x,y:335,vx:direction*155,vy:0});tone(180,.1);}
for(const shot of boss.shots){shot.x+=shot.vx*dt;shot.y+=shot.vy*dt;}boss.shots=boss.shots.filter(q=>q.x>-25&&q.x<925);
const onHead=p.x+p.w>boss.x-35&&p.x<boss.x+35&&previousBottom<=boss.y+3&&p.y+p.h>=boss.y&&p.vy>0;
if(onHead){p.y=boss.y-p.h;p.vy=-540;p.jumps=0;p.ground=false;p.riding=null;if(boss.cooldown===0){boss.hp--;boss.cooldown=1;burst(boss.x,boss.y,'#f0ce71',24);tone(900,.15);say(boss.hp?'命中！再踩 '+boss.hp+' 次。':'Boss 已击败，前往右侧金色门！');if(boss.hp===0){boss.shots=[];return;}}}
if(boss.cooldown===0&&p.x+p.w>boss.x-37&&p.x<boss.x+37&&p.y+p.h>boss.y+6&&p.y<440){fail();return;}
if(boss.cooldown===0)for(const q of boss.shots)if(circleHitsPlayer(q.x,q.y,10)){fail();return;}}
function update(dt){if(state!=='playing')return;updatePosture();t+=dt;portalCooldown=Math.max(0,portalCooldown-dt);const L=levels[index];advanceTiles(dt);
if(p.riding!==null){const tile=tiles[p.riding];if(tile.active&&p.ground){p.x+=tile.dx;p.y+=tile.dy;}else{p.riding=null;p.ground=false;p.jumps=Math.max(1,p.jumps);}}
const oldX=p.x,oldY=p.y;const belt=p.riding!==null&&tiles[p.riding].kind==='belt'?tiles[p.riding].amount:0;const wind=!p.ground?(L.wind||0):0;p.vx=((keys.right?1:0)-(keys.left?1:0))*(p.crouched?125:235)+belt+wind;p.x=Math.max(0,Math.min(900-p.w,p.x+p.vx*dt));
for(const [x,y] of L.spikes){const bounds=spikeBounds(x,y,p.y,p.y+p.h);if(!bounds)continue;const [left,right]=bounds;if(p.vx>0&&oldX+p.w<=left+.001&&p.x+p.w>left){p.x=left-p.w;p.vx=0;}else if(p.vx<0&&oldX>=right-.001&&p.x<right){p.x=right;p.vx=0;}}
for(const [x,y,w,h]of L.beams||[]){if(p.y+p.h>y&&p.y<y+h){if(oldX+p.w<=x&&p.x+p.w>x){p.x=x-p.w;p.vx=0;}else if(oldX>=x+w&&p.x<x+w){p.x=x+w;p.vx=0;}}}
const bottom=p.y+p.h;p.vy+=1150*dt;p.y+=p.vy*dt;const nextBottom=p.y+p.h,was=p.ground;p.ground=false;p.riding=null;
// Pick the first crossed surface, independent of route/platform declaration order.
let landing=-1,top=Infinity;for(let i=0;i<tiles.length;i++){const q=tiles[i];if(q.active&&p.vy>=0&&bottom<=q.y+1&&p.y+p.h>=q.y&&p.x+p.w>q.x+2&&p.x<q.x+q.w-2&&q.y<top){landing=i;top=q.y;}}
if(landing>=0){const q=tiles[landing];p.y=q.y-p.h;p.vy=0;p.ground=true;p.jumps=0;p.riding=landing;if(q.kind==='crumble'&&q.trigger<0)q.trigger=0;}
for(const [x,y,w,h]of L.beams||[]){if(p.x+p.w>x&&p.x<x+w){if(p.vy<0&&oldY>=y+h&&p.y<y+h){p.y=y+h;p.vy=0;}else if(p.vy>=0&&bottom<=y&&p.y+p.h>=y){p.y=y-p.h;p.vy=0;p.ground=true;p.jumps=0;}}}
if(!p.ground){if(was)p.coyote=.09;p.coyote-=dt;if(p.coyote<=0&&p.jumps===0)p.jumps=1;}
for(const [x,y]of L.spikes){const tipX=x+14,tipY=y-25;if(nextBottom>bottom&&bottom<=tipY&&p.y+p.h>=tipY&&p.x<tipX&&p.x+p.w>tipX){fail();return;}if(oldY>=y&&p.y<y&&p.x+p.w>x&&p.x<x+28){p.y=y;p.vy=0;continue;}const bounds=spikeBounds(x,y,p.y,p.y+p.h);if(bounds&&p.x+p.w>bounds[0]&&p.x<bounds[1]){p.x=p.x+p.w/2<tipX?bounds[0]-p.w:bounds[1];p.vx=0;}}
// Spring pads may sit on a larger normal platform; detect them separately.
if(p.ground){for(const q of tiles)if(q.kind==='spring'&&Math.abs(p.y+p.h-q.y)<1&&p.x+p.w>q.x+3&&p.x<q.x+q.w-3){p.vy=-690;p.jumps=0;p.ground=false;p.riding=null;burst(p.x+14,q.y,'#f0a0c6');tone(540,.18);break;}}
for(const h of hammerPositions())if(circleHitsPlayer(h.x,h.y,18)){fail();return;}
if(p.y>560){fail();return;}
for(const [x,y,tx,ty] of L.portals||[])if(portalCooldown===0&&Math.abs(p.x+14-x)<23&&Math.abs(p.y+p.h-y)<45){p.x=tx-14;p.y=ty-p.h;p.vx=p.vy=0;p.jumps=0;p.ground=false;p.riding=null;portalCooldown=1.2;burst(tx,ty-25,'#b8a0e7');say('传送成功！也可以重玩试试另一条路线。');tone(780,.16);break;}
const [cx,cy]=L.checkpoint;if(!checkpoint&&p.ground&&Math.abs(p.x+14-cx)<35&&Math.abs(p.y+p.h-cy)<2){checkpoint=true;$('checkpoint').textContent='⚑ 检查点已激活';say('检查点已激活！失误后从绿旗继续。');tone(650,.15);}
if(L.key&&!collectedKey&&Math.hypot(p.x+14-L.key[0],p.y+p.h/2-L.key[1])<28){collectedKey=true;say('钥匙拿到了！终点已解锁。');$('route').textContent=L.route+' ✓';tone(820,.2);}
updateBoss(dt,bottom);if(state!=='playing')return;
for(const s of stars)if(!s.got&&Math.hypot(p.x+14-s.x,p.y+p.h/2-s.y)<30){s.got=true;burst(s.x,s.y,'#e3b64f');tone(720,.14);}
if((!boss||boss.hp===0)&&(!L.key||collectedKey)&&stars.filter(s=>s.got).length>=(L.requiredStars||0)&&Math.abs(p.x+14-L.goal[0])<26&&p.y+p.h<=L.goal[1]+4&&p.y+p.h>L.goal[1]-70){win();return;}
particles.forEach(a=>{a.x+=a.vx*dt;a.y+=a.vy*dt;a.life-=dt});particles=particles.filter(a=>a.life>0);hud();}
function round(x,y,w,h,r,fill){ctx.fillStyle=fill;ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill();}
function cloud(x,y,s=1){ctx.fillStyle='#ffffff80';ctx.beginPath();ctx.ellipse(x,y,48*s,12*s,0,0,Math.PI*2);ctx.ellipse(x-17*s,y-10*s,20*s,18*s,0,0,Math.PI*2);ctx.ellipse(x+8*s,y-13*s,25*s,22*s,0,0,Math.PI*2);ctx.fill();}
function star(x,y,r,color){ctx.fillStyle=color;ctx.beginPath();for(let i=0;i<10;i++){let a=i*Math.PI/5-Math.PI/2,rr=i%2?r*.46:r;ctx.lineTo(x+Math.cos(a)*rr,y+Math.sin(a)*rr)}ctx.closePath();ctx.fill();}
function draw(now){now=t;const L=levels[index];ctx.fillStyle=L.color;ctx.fillRect(0,0,900,510);const sky=ctx.createLinearGradient(0,0,0,510);sky.addColorStop(0,'#ffffff15');sky.addColorStop(1,'#ffffff88');ctx.fillStyle=sky;ctx.fillRect(0,0,900,510);ctx.fillStyle='#fff8d6bb';ctx.beginPath();ctx.arc(716,94,43,0,Math.PI*2);ctx.fill();cloud(145+Math.sin(now*.08)*12,95,1);cloud(480,145,.7);cloud(825,170,.6);
for(let layer=0;layer<2;layer++){ctx.fillStyle=layer?'#adc4ab55':'#b4cbba66';ctx.beginPath();ctx.moveTo(0,510);for(let x=0;x<=900;x+=10)ctx.lineTo(x,345+layer*70+Math.sin(x*.008+layer*2)*50+Math.sin(x*.017)*20);ctx.lineTo(900,510);ctx.fill();}
for(const q of tiles){const {x,y,w,kind}=q;ctx.save();if(!q.active)ctx.globalAlpha=.15;const color={normal:'#6d946b',move:'#6b9fc4',lift:'#598fbc',phase:'#9e9bd2',spring:'#d987b3',crumble:'#d7a15f',belt:'#4faaa3'}[kind];round(x+4,y+8,w,25,10,'#7591741b');round(x,y,w,22,8,color);round(x+4,y+4,w-8,4,2,'#ffffff66');ctx.fillStyle='#fff';ctx.font='bold 13px sans-serif';ctx.textAlign='center';if(kind!=='normal')ctx.fillText({move:'↔',lift:'↕',phase:q.active?'◷':'·',spring:'↑↑',crumble:q.trigger>=0&&q.active?Math.max(0,(L.crumbleDelay||.9)-q.trigger).toFixed(1):'···',belt:q.amount>0?'› › ›':'‹ ‹ ‹'}[kind],x+w/2,y+18);if(kind==='crumble'&&q.trigger>=0&&q.active){round(x,y-5,w*Math.max(0,1-q.trigger/(L.crumbleDelay||.9)),3,1,'#df8c53');}ctx.restore();}
for(const [x,y,w,h]of L.beams||[]){round(x,y,w,h,8,'#829889');round(x,y+h-8,w,8,3,'#c7d6b9');ctx.fillStyle='#fff';ctx.font='12px sans-serif';ctx.fillText('↓ 蹲下通过',x+15,y+h-20);}
// Gates, checkpoint flags and swinging hazards are drawn in world coordinates.
for(const [pair,[x,y,tx,ty]]of (L.portals||[]).entries()){const suffix=L.portals.length>1?String(pair+1):'';for(const [px,py,label]of [[x,y,'A'+suffix+' →'],[tx,ty,'B'+suffix]]){ctx.save();ctx.strokeStyle='#a28acf';ctx.lineWidth=4;ctx.setLineDash([6,3]);ctx.beginPath();ctx.ellipse(px,py-28,20,29,0,0,Math.PI*2);ctx.stroke();ctx.fillStyle='#a28acf';ctx.font='bold 12px sans-serif';ctx.textAlign='center';ctx.fillText(label,px,py-66);ctx.restore();}}
const [cx,cy]=L.checkpoint;ctx.strokeStyle='#6b8971';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(cx,cy);ctx.lineTo(cx,cy-50);ctx.stroke();ctx.fillStyle=checkpoint?'#4aaf7b':'#a5bbae';ctx.beginPath();ctx.moveTo(cx,cy-50);ctx.lineTo(cx+27,cy-40);ctx.lineTo(cx,cy-30);ctx.fill();
for(const h of hammerPositions()){ctx.strokeStyle='#8d7d98';ctx.lineWidth=5;ctx.beginPath();ctx.moveTo(h.anchorX,h.anchorY);ctx.lineTo(h.x,h.y);ctx.stroke();ctx.fillStyle='#cf7b8e';ctx.beginPath();ctx.arc(h.x,h.y,18,0,Math.PI*2);ctx.fill();ctx.fillStyle='#ffffff88';ctx.beginPath();ctx.arc(h.x-5,h.y-5,5,0,Math.PI*2);ctx.fill();}
if(L.wind){ctx.fillStyle='#688c8a';ctx.font='12px sans-serif';ctx.fillText(L.wind>0?'风向 →':'风向 ←',35,55);}
for(const[x,y]of L.spikes){ctx.fillStyle='#bf7872';ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+14,y-25);ctx.lineTo(x+28,y);ctx.closePath();ctx.fill();ctx.fillStyle='#ead2bd';ctx.beginPath();ctx.moveTo(x+14,y-25);ctx.lineTo(x+8,y-14);ctx.lineTo(x+19,y-14);ctx.fill()}
if(L.key&&!collectedKey){ctx.strokeStyle='#ce9c37';ctx.lineWidth=4;const[kx,ky]=L.key;ctx.beginPath();ctx.arc(kx,ky,7,0,Math.PI*2);ctx.moveTo(kx+7,ky);ctx.lineTo(kx+24,ky);ctx.lineTo(kx+24,ky+6);ctx.moveTo(kx+18,ky);ctx.lineTo(kx+18,ky+5);ctx.stroke();}
if(boss&&boss.hp>0){ctx.save();if(boss.cooldown>0)ctx.globalAlpha=.55+.45*Math.sin(t*25)**2;round(boss.x-38,boss.y,76,70,22,'#9271b5');round(boss.x-30,boss.y-7,60,14,6,'#f5cf72');round(boss.x-23,boss.y+20,12,13,4,'#fff5eb');round(boss.x+11,boss.y+20,12,13,4,'#fff5eb');round(boss.x-19,boss.y+25,5,8,2,'#453657');round(boss.x+14,boss.y+25,5,8,2,'#453657');round(boss.x-14,boss.y+48,28,5,2,'#624678');ctx.restore();const interval=boss.hp<=2?1.9:2.8;if(boss.clock>interval-.65){ctx.fillStyle='#ca6477';ctx.font='bold 16px sans-serif';ctx.textAlign='center';ctx.fillText('! 即将发射',boss.x,boss.y-25);ctx.textAlign='start';}for(const q of boss.shots){ctx.fillStyle='#db768b';ctx.beginPath();ctx.arc(q.x,q.y,10,0,Math.PI*2);ctx.fill();}}
const[gx,gy]=L.goal;ctx.save();ctx.shadowColor='#f5d37d';ctx.shadowBlur=22;round(gx-22,gy-66,44,66,[22,22,0,0],'#f9e5a2');ctx.shadowBlur=0;round(gx-15,gy-58,30,58,[15,15,0,0],'#ffffe4');star(gx,gy-34+Math.sin(now*3)*3,10,'#d7ae55');ctx.restore();if((boss&&boss.hp>0)||(L.key&&!collectedKey)||stars.filter(s=>s.got).length<(L.requiredStars||0)){round(gx-12,gy-44,24,22,5,'#7d7891');ctx.fillStyle='white';ctx.font='14px sans-serif';ctx.fillText('×',gx-4,gy-28);}
for(const s of stars)if(!s.got){ctx.save();ctx.shadowColor='#e7c66a';ctx.shadowBlur=12;star(s.x,s.y+Math.sin(now*3+s.x)*4,12,'#e0ad3d');ctx.restore();star(s.x-2,s.y-2+Math.sin(now*3+s.x)*4,4,'#fff1b3')}
let e=enemy();if(e){ctx.fillStyle='#c5756f';ctx.beginPath();ctx.arc(e.x,e.y,17,0,Math.PI*2);ctx.fill();round(e.x-8,e.y-5,5,6,2,'#fff');round(e.x+3,e.y-5,5,6,2,'#fff');}
ctx.save();ctx.translate(p.x+p.w/2,p.y+p.h/2);ctx.rotate(p.vx*.00012);if(p.crouched){round(-14,-9,28,18,7,'#f6f3d9');round(-12,-9,24,8,[7,7,2,2],'#4e775b');round(-16,-3,32,4,2,'#4e775b');round(-14,5,28,4,2,'#e7b65e');ctx.fillStyle='#344e40';ctx.fillRect(-6,1,3,3);ctx.fillRect(4,1,3,3);round(-13,7,10,3,2,'#465e45');round(3,7,10,3,2,'#465e45');}else{round(-14,-17,28,35,10,'#f6f3d9');round(-12,-18,24,15,[9,9,3,3],'#4e775b');round(-17,-8,34,6,3,'#4e775b');round(-15,10,30,6,3,'#e7b65e');ctx.fillStyle='#344e40';ctx.fillRect(-6,1,3,4);ctx.fillRect(4,1,3,4);round(-10,17,8,4,2,'#465e45');round(3,17,8,4,2,'#465e45');}ctx.restore();
for(const a of particles){ctx.globalAlpha=Math.max(0,a.life/.6);round(a.x,a.y,4,4,2,a.color)}ctx.globalAlpha=1;ctx.fillStyle='#64816866';ctx.font='10px sans-serif';ctx.fillText('START',35,levels[index].platforms[0][1]+34);}
function loop(ms){let dt=Math.min((ms-last)/1000,.05);last=ms;acc+=dt;while(acc>=1/120){update(1/120);acc-=1/120;}draw(ms/1000);requestAnimationFrame(loop)}
document.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','KeyS','Space','KeyA','KeyD','KeyW','KeyR','KeyP','Escape'].includes(e.code)){if(e.target.tagName==='BUTTON'&&e.code==='Space')return;e.preventDefault();if(['ArrowDown','KeyS'].includes(e.code))setCrouchInput(e.code,true);if(e.code==='ArrowLeft'||e.code==='KeyA')keys.left=true;if(e.code==='ArrowRight'||e.code==='KeyD')keys.right=true;if(!e.repeat){if(['Space','ArrowUp','KeyW'].includes(e.code))jump();if(e.code==='KeyR')load(index,true);if(e.code==='KeyP'||e.code==='Escape')pause();}}});document.addEventListener('keyup',e=>{if(['ArrowDown','KeyS'].includes(e.code))setCrouchInput(e.code,false);if(['ArrowLeft','KeyA'].includes(e.code))keys.left=false;if(['ArrowRight','KeyD'].includes(e.code))keys.right=false;});window.addEventListener('blur',()=>{resetControls();if(state==='playing')pause()});document.addEventListener('visibilitychange',()=>{if(document.hidden){resetControls();if(state==='playing')pause()}});
document.querySelectorAll('[data-key]').forEach(b=>{b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);if(b.dataset.key==='jump')jump();else if(b.dataset.key==='crouch')setCrouchInput('pointer-'+e.pointerId,true);else keys[b.dataset.key]=true;});for(const ev of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(ev,e=>{if(b.dataset.key==='crouch')setCrouchInput('pointer-'+e.pointerId,false);else if(b.dataset.key!=='jump')keys[b.dataset.key]=false})});$('pause').onclick=pause;$('restart').onclick=()=>load(index,true);$('sound').onclick=()=>{muted=!muted;$('sound').textContent=muted?'♪ ×':'♪';$('sound').setAttribute('aria-label',muted?'开启音效':'关闭音效');tone(600)};$('action').onclick=()=>{load(index,true);$('action').blur()};load(0);requestAnimationFrame(loop);
